var spriteKey = null;
var sheetCache = {};

// Sprite filenames are hash-named per deploy now (see main()'s sprite
// loop) — sprite-worker.js is itself a stale-while-revalidate pointer
// file (listed in sw.js's FILES), so baking a per-deploy filename map
// directly into this generated script's text would reintroduce the same
// staleness bug the shell/data split was built to fix: a stale cached
// copy of THIS script would keep requesting stale-hash sprite filenames
// forever. build-manifest.json is fetched fresh (cache:'no-store') here
// for the same reason the main thread does it — it's the one thing that
// must always reflect the CURRENT deploy.
var manifestReady = fetch('build-manifest.json', { cache: 'no-store' }).then(function(r) { return r.json(); });

function attemptSheetLoad(sheetIdx) {
  return manifestReady.then(function(m) {
    return fetch(m.sprites[sheetIdx].file);
  })
    .then(function(r) { return r.arrayBuffer(); })
    .then(function(buf) {
      var bytes = new Uint8Array(buf);
      var iv = bytes.slice(0, 12), data = bytes.slice(12);
      return crypto.subtle.decrypt({ name: 'AES-GCM', iv: iv }, spriteKey, data);
    })
    .then(function(plainBuf) {
      return createImageBitmap(new Blob([plainBuf], { type: 'image/jpeg' }));
    });
}
// Same empirically-necessary retry as before the worker move (see the
// earlier concurrency-flakiness investigation) — crypto.subtle.decrypt()
// occasionally throws OperationError under heavy simultaneous load even
// on verified-correct bytes; retrying the whole chain a few times is
// cheap and makes it a non-issue in practice.
function getSheetImage(sheetIdx, attemptsLeft) {
  if (attemptsLeft === undefined) attemptsLeft = 3;
  if (sheetCache[sheetIdx]) return sheetCache[sheetIdx];
  var p = attemptSheetLoad(sheetIdx).catch(function(err) {
    if (attemptsLeft > 1) {
      delete sheetCache[sheetIdx];
      return getSheetImage(sheetIdx, attemptsLeft - 1);
    }
    return null;
  });
  sheetCache[sheetIdx] = p;
  return p;
}

self.onmessage = function(e) {
  var msg = e.data;
  if (msg.type === 'init') {
    spriteKey = msg.key;
    return;
  }
  if (msg.type !== 'resolve') return;
  var entry = MANIFEST.images[msg.thumbPath];
  if (!entry || !spriteKey) {
    self.postMessage({ id: msg.id, thumbPath: msg.thumbPath, blob: null });
    return;
  }
  getSheetImage(entry.sheet).then(function(sheetImg) {
    if (!sheetImg) {
      self.postMessage({ id: msg.id, thumbPath: msg.thumbPath, blob: null });
      return;
    }
    var CELL = MANIFEST.cell;
    var canvas = new OffscreenCanvas(CELL, CELL);
    var ctx = canvas.getContext('2d');
    ctx.drawImage(sheetImg, entry.col * CELL, entry.row * CELL, CELL, CELL, 0, 0, CELL, CELL);
    canvas.convertToBlob({ type: 'image/jpeg', quality: 0.9 }).then(function(blob) {
      self.postMessage({ id: msg.id, thumbPath: msg.thumbPath, blob: blob });
    });
  });
};
